import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync, existsSync} from 'node:fs';
import {createRequire} from 'node:module';
const pc=createRequire(import.meta.url)('../product-content.js');
const html=readFileSync(new URL('../blog/done-by-deer/index.html',import.meta.url),'utf8');
const brand='丹麥 Done by deer兒童用品';
const row={'品牌':brand,'連結':'https://example.com/offer','類型':'短期','開團日期':'2026-01-10','結束日期':'2026-01-20'};

test('done-by-deer: catalog binds only the exact Sheet brand',()=>{
 assert.equal(pc.entry(brand)?.id,'done-by-deer');
 assert.equal(pc.entry(brand.slice(0,-1)),undefined);
 for(const image of [pc.entry(brand).image,pc.entry(brand).cardImage].filter(Boolean))assert.ok(existsSync(new URL('..'+image,import.meta.url)),image);
});
test('done-by-deer: offer follows the Sheet dates and fails closed',()=>{
 assert.equal(pc.campaignFor([row],'doneByDeer','2026-01-10').state,'open');
 assert.equal(pc.campaignFor([row],'doneByDeer','2026-01-21').state,'closed');
 assert.equal(pc.campaignFor([row],'doneByDeer','2026-01-09').state,'upcoming');
 assert.equal(pc.campaignFor([row,row],'doneByDeer','2026-01-15').state,'unavailable');
 assert.equal(pc.campaignFor([],'doneByDeer','2026-01-15').state,'unavailable');
});
test('done-by-deer: one H1, resolvable chapters, crawlable fallback',()=>{
 assert.equal((html.match(/<h1\b/g)||[]).length,1);
 const nav=html.match(/<nav[^>]*data-reading-nav[^>]*>([\s\S]*?)<\/nav>/)?.[1]||'';
 for(const [,id] of nav.matchAll(/href="#([^"]+)"/g))assert.match(html,new RegExp(`id="${id}"`),id);
 assert.match(html,/<noscript>[\s\S]*?href="\/"/);
 assert.doesNotMatch(html,/https:\/\/example\.com\/offer/);
});
test('done-by-deer: listed in the journal with a hidden buy link',()=>{
 const card=readFileSync(new URL('../blog/index.html',import.meta.url),'utf8').match(/<article class="article-card" data-article="doneByDeer"[\s\S]*?<\/article>/)?.[0];
 assert.ok(card,'journal card');
 assert.ok(card.includes('<a class="buy" data-buy hidden>'));
});
